#include <algorithm>
#include <functional>
#include <iostream>
#include <queue>
#include <vector>
using namespace std;
int main(){int n;cin>>n;vector<pair<long long,long long>> a(n);
for(auto &v:a)cin>>v.first>>v.second;sort(a.begin(),a.end());
priority_queue<long long,vector<long long>,greater<long long>> q;size_t peak=0;
for(auto v:a){
while(!q.empty()&&q.top()<=v.first)q.pop();
q.push(v.second);peak=max(peak,q.size());
}
cout<<peak<<'\n';}

