#include <iostream>
#include <iterator>
#include <set>
#include <vector>
using namespace std;
int main(){int n,k;cin>>n>>k;vector<int>a(n),next(n),last(100001,n);
for(int &x:a)cin>>x;
for(int i=n-1;i>=0;--i){next[i]=last[a[i]];last[a[i]]=i;}
set<pair<int,int>> cache;int misses=0;
for(int i=0;i<n;++i){int x=a[i];
if(cache.erase({i,x})==0){++misses;
if(cache.size()==static_cast<size_t>(k))cache.erase(prev(cache.end()));
}
cache.insert({next[i],x});
}
cout<<misses<<'\n';}

